export const nodes = Object.fromEntries(story.map(n=>[n.id,n]));
export function freshState() {return {version:1,node:'alarm',companion:'blob',traits:{heart:0,spark:0,guts:0},flags:[],items:[],trail:[],end:null};}
export function choose(state,choice) {
 const next=structuredClone(state);
 next.trail.push({node:state.node,label:choice.label});
 if(choice.trait) next.traits[choice.trait]++;
 if(choice.flag&&!next.flags.includes(choice.flag))next.flags.push(choice.flag);
 if(choice.item&&!next.items.includes(choice.item))next.items.push(choice.item);
 if(choice.companion)next.companion=choice.companion;
 if(choice.ending) {next.end=choice.ending==='together'&&next.traits.heart<3&&!next.flags.includes('listened')?'loop':choice.ending;next.node='ending';}
 else next.node=choice.next;
 const item=nodes[next.node]?.item;if(item&&!next.items.includes(item))next.items.push(item);
 return next;
}
